using ghidra.app.plugin.core.debug.service.tracermi;
using ghidra.app.script;
using ghidra.app.services;
using ghidra.debug.api.tracermi;

public class ListenTraceRmiScript : GhidraScript {

	TraceRmiService getService()
    {
		TraceRmiService service = state.getTool().getService(typeof(TraceRmiService));
		if (service != null) {
			return service;
		}
		state.getTool().addPlugin(typeof(TraceRmiPlugin).getName());
		return Objects.requireNonNull(state.getTool().getService(typeof(TraceRmiService)));
	}

	/* @Override */
	protected void run()
    {
		TraceRmiService service = getService();

		TraceRmiAcceptor acceptor = service.acceptOne(null);
		println("Listening at " + acceptor.getAddress());
		TraceRmiConnection connection = acceptor.accept();
		println("Connection from " + connection.getRemoteAddress());

		RemoteMethod execute = connection.getMethods().get("execute");
		if (execute == null) {
			printerr("No execute method!");
		}
		while (true) {
			string cmd = askString("Execute", "command?");
			try {
				execute.invoke(Map.of("cmd", cmd));
			}
			catch (TraceRmiError e) {
				printerr(e.getMessage());
			}
		}
	}
}
